-- Candidate alternative accounting. Only GameCore may mutate this queue.
-- Native promotion receipts are generated by GovernorPromotionModifiers;
-- neither UI parameters nor an increase in spent points can create a receipt.
JAC_TitlePaymentRules = {};
local Rules = JAC_TitlePaymentRules;
local PREFIX = 'JAC_PERSONA_';
local QUEUE = 'JAC_PROXY_PAYMENT_QUEUE_';
local MAX_PAYMENTS = 66;

local function Person(leader, field)
    return Game:GetProperty(PREFIX .. leader .. '_' .. field);
end;
local function Owned(owner, leader)
    local player = Players[owner];
    local row = type(leader) == 'string' and GameInfo.JAC_LeaderPersonas[leader];
    local state = row and Person(leader, 'STATE');
    return player and player:IsAlive() and player:IsMajor() and row and
        Person(leader, 'OWNER') == owner and (state == 'GREAT_PERSON' or state == 'EVOLVING');
end;
function Rules.Valid(owner, leader)
    if not Owned(owner, leader) then return false, 'OWNER_CHANGED'; end;
    local row = GameInfo.JAC_LeaderPersonas[leader];
    local individual = GameInfo.GreatPersonIndividuals[row.PersonType];
    local class = individual and GameInfo.GreatPersonClasses[individual.GreatPersonClassType];
    local definition = class and GameInfo.Units[class.UnitType];
    if not definition then return false, 'PERSON_MISSING'; end;
    local count = 0;
    for _, unit in Players[owner]:GetUnits():Members() do
        if unit:GetType() == definition.Index then
            local gp = unit:GetGreatPerson();
            local index = gp and gp:GetIndividual();
            local person = index ~= nil and index ~= -1 and GameInfo.GreatPersonIndividuals[index];
            if person and person.GreatPersonIndividualType == row.PersonType then count = count + 1; end;
        end;
    end;
    return count == 1, count == 1 and nil or 'PERSON_MISSING';
end;
local function Receipt(owner, stage)
    return Players[owner]:GetProperty('JAC_PROXY_NATIVE_PAID_' .. stage);
end;
local function Save(owner, queue) Game:SetProperty(QUEUE .. owner, queue); end;
local function Outstanding(queue)
    local reserved = 0;
    for _, request in ipairs(queue.requests) do
        if request.status == 'PENDING' then reserved = reserved + request.cost - #request.payments; end;
    end;
    return reserved;
end;
local function Funded(owner, queue, request)
    local governors = Players[owner]:GetGovernors();
    local others = Outstanding(queue) - (request.cost - #request.payments);
    return governors:GetGovernorPoints() - governors:GetGovernorPointsSpent() - others >= 1;
end;

function Rules.Queue(owner) return Game:GetProperty(QUEUE .. owner); end;
function Rules.Request(owner, leader)
    Rules.Reconcile(owner);
    local queue = Rules.Queue(owner);
    for _, request in ipairs(queue and queue.requests or {}) do
        if request.leader == leader then
            return request.status == 'PAID' and 'ALREADY_PAID' or request.status;
        end;
    end;
    if not Owned(owner, leader) then return 'NOT_OWNED'; end;
    if not Rules.Valid(owner, leader) then return 'PERSON_MISSING'; end;
    local row = GameInfo.JAC_LeaderPersonas[leader];
    local cost = Person(leader, 'EVOLUTION_COST') or row.EvolutionCost;
    if type(cost) ~= 'number' or cost % 1 ~= 0 or cost < 1 or cost > 3 then return 'INVALID_COST'; end;
    if not queue then
        for stage = 0, MAX_PAYMENTS - 1 do
            local paid = Receipt(owner, stage);
            if paid ~= nil and paid ~= 0 then return 'UNEXPECTED_NATIVE_PAYMENT'; end;
        end;
        queue = {cursor=0, serial=0, requests={}, spentFloor=Players[owner]:GetGovernors():GetGovernorPointsSpent()};
    end;
    local governors = Players[owner]:GetGovernors();
    local available = governors:GetGovernorPoints() - governors:GetGovernorPointsSpent();
    local reserved = Outstanding(queue);
    if available - reserved < cost then return 'NO_TITLE'; end;
    if queue.cursor + reserved + cost > MAX_PAYMENTS then return 'PAYMENT_LIMIT'; end;
    queue.serial = queue.serial + 1;
    queue.requests[#queue.requests + 1] = {id=queue.serial, leader=leader, cost=cost,
        status='PENDING', payments={}, spentAtRequest=governors:GetGovernorPointsSpent()};
    Save(owner, queue);
    return 'PENDING';
end;

-- A descriptor for the synchronized native APPOINT/PROMOTE request, not proof
-- that the request ran. Repeated reads never change reservations or balances.
function Rules.Next(owner)
    local queue = Rules.Queue(owner);
    if not queue or queue.cursor >= MAX_PAYMENTS then return nil; end;
    if queue.flight then
        for _, request in ipairs(queue.requests) do
            if request.id == queue.flight.request then
                if request.status ~= 'PENDING' or not Rules.Valid(owner, request.leader) then return nil; end;
                if not Funded(owner, queue, request) then return nil; end;
                return {request=request.id, leader=request.leader, stage=queue.flight.stage,
                    action=queue.flight.stage == 0 and 'APPOINT' or 'PROMOTE'};
            end;
        end;
        return nil;
    end;
    for _, request in ipairs(queue.requests) do
        if request.status == 'PENDING' then
            if not Rules.Valid(owner, request.leader) then return nil; end;
            if not Funded(owner, queue, request) then return nil; end;
            return {request=request.id, leader=request.leader, stage=queue.cursor,
                action=queue.cursor == 0 and 'APPOINT' or 'PROMOTE'};
        end;
    end;
    return nil;
end;

-- Preparation cannot send Native. Only Authorize grants a single attempt;
-- after that grant the result may be unknown, even if UI never sent Native.
function Rules.Begin(owner)
    Rules.Reconcile(owner);
    local queue = Rules.Queue(owner);
    if not queue then return 'NO_REQUEST'; end;
    if queue.flight then return 'ALREADY_STARTED'; end;
    local next = Rules.Next(owner);
    if not next then return 'NOT_READY'; end;
    local paid = Receipt(owner, next.stage);
    if paid ~= nil and paid ~= 0 then return 'UNEXPECTED_NATIVE_PAYMENT'; end;
    queue.flightSerial = (queue.flightSerial or 0) + 1;
    queue.flight = {id=queue.flightSerial, request=next.request, stage=next.stage,
        state='PREPARED', attempt=0};
    Save(owner, queue);
    return 'STARTED';
end;

-- Only gameplay calls this transition. A cancelled request keeps the receipts
-- already consumed for it; its unspent reservation is released for later people.
function Rules.Reconcile(owner)
    local queue = Rules.Queue(owner);
    if not queue or not Players[owner] then return 'NO_REQUEST'; end;
    local changed, cancelled = false, false;
    -- Old saves did not distinguish preparation from dispatch. Never infer
    -- "unsent" from a missing receipt, a UI reload, or elapsed time.
    if queue.flight and not queue.flight.state then
        queue.flightSerial = (queue.flightSerial or 0) + 1;
        queue.flight.id = queue.flightSerial;
        queue.flight.state = 'AUTHORIZED';
        queue.flight.attempt = 0;
        queue.flight.lastAttemptTurn = Game.GetCurrentGameTurn();
        queue.flight.spentBefore = queue.spentFloor;
        changed = true;
    end;
    for _, request in ipairs(queue.requests) do
        if request.status == 'PENDING' then
            local valid, reason = Rules.Valid(owner, request.leader);
            if not valid then
                request.status, request.reason = 'CANCELLED', reason;
                changed = true;
                cancelled = true;
            end;
        end;
        local flight = queue.flight;
        if request.status == 'CANCELLED' and flight and flight.request == request.id and
            flight.state == 'PREPARED' then
            local paid = Receipt(owner, flight.stage);
            if paid == nil or paid == 0 then
                -- A delayed Authorize message carries this flight ID and will
                -- be rejected after release, even if the stage is reused.
                flight.state = 'ABORTED_UNSENT';
                request.abortedFlight = flight;
                queue.flight = nil;
                changed = true;
            end;
        end;
    end;
    if changed then Save(owner, queue); return cancelled and 'CANCELLED' or 'RECONCILED'; end;
    return 'UNCHANGED';
end;

-- Compare-and-swap authorization of this exact native stage. The persisted
-- turn, not an UI-local attempted set, decides retry eligibility. Retries can
-- only target the same APPOINT/promotion; Native's acquisition/eligibility
-- check makes a repeated operation on that stage idempotent.
function Rules.Authorize(owner, id, requestID, stage, attempt)
    Rules.Reconcile(owner);
    local queue = Rules.Queue(owner);
    local flight = queue and queue.flight;
    if not flight or flight.id ~= id or flight.request ~= requestID or flight.stage ~= stage then
        return 'STALE_FLIGHT';
    end;
    if flight.attempt ~= attempt then return 'STALE_ATTEMPT'; end;
    local paid = Receipt(owner, stage);
    if paid == 1 then return 'RECEIPT_READY'; end;
    if paid ~= nil and paid ~= 0 then return 'INVALID_RECEIPT'; end;
    local next = Rules.Next(owner);
    if not next then return 'NOT_READY'; end;
    local turn = Game.GetCurrentGameTurn();
    if flight.lastAttemptTurn and flight.lastAttemptTurn >= turn then return 'WAIT_NEXT_TURN'; end;
    local governors = Players[owner]:GetGovernors();
    local spent = governors:GetGovernorPointsSpent();
    flight.state = 'AUTHORIZED';
    flight.attempt = attempt + 1;
    flight.lastAttemptTurn = turn;
    -- Keep the FIRST authorization's floor: a retry must not hide spending
    -- whose native modifier receipt has not been published yet.
    if flight.spentBefore == nil then flight.spentBefore = spent; end;
    Save(owner, queue);
    return 'AUTHORIZED';
end;

function Rules.Advance(owner)
    Rules.Reconcile(owner);
    local queue = Rules.Queue(owner);
    if not queue or not Players[owner] then return 'NO_REQUEST'; end;
    local flight = queue.flight;
    if not flight then return 'NO_STARTED_STAGE'; end;
    for _, request in ipairs(queue.requests) do
        if request.id == flight.request then
            local paid = Receipt(owner, flight.stage);
            if paid == nil or paid == 0 then return 'NATIVE_PENDING'; end;
            if paid ~= 1 then return 'INVALID_RECEIPT'; end;
            if flight.state ~= 'AUTHORIZED' then return 'UNEXPECTED_NATIVE_PAYMENT'; end;
            -- A native payment must also be reflected in the official spent
            -- count. Other governors' expenses cannot stand in for this marker.
            local spent = Players[owner]:GetGovernors():GetGovernorPointsSpent();
            if spent <= math.max(queue.spentFloor, flight.spentBefore or queue.spentFloor) then
                return 'ACCOUNTING_PENDING';
            end;
            if flight.stage ~= queue.cursor then return 'INVALID_STAGE'; end;
            request.payments[#request.payments + 1] = flight.stage;
            queue.cursor = flight.stage + 1;
            queue.spentFloor = spent;
            queue.flight = nil;
            if request.status ~= 'CANCELLED' and #request.payments == request.cost then request.status = 'PAID'; end;
            Save(owner, queue);
            if request.status == 'CANCELLED' then return 'CANCELLED_PAYMENT'; end;
            return request.status == 'PAID' and 'PAID' or 'PARTIAL';
        end;
    end;
    return 'NO_PENDING_REQUEST';
end;

function Rules.Paid(owner, leader)
    local queue = Rules.Queue(owner);
    if not queue then return false; end;
    for _, request in ipairs(queue.requests) do
        if request.leader == leader and request.status == 'PAID' and #request.payments == request.cost then
            for _, stage in ipairs(request.payments) do if Receipt(owner, stage) ~= 1 then return false; end; end;
            return true;
        end;
    end;
    return false;
end;
